#!/usr/bin/env python3
"""Build the INTJ ATLAS homepage from `site/` sources and `data/catalog.json`.

The site ships three standalone HTML pages:

* ``index.html``   — generated by this script (never edit it by hand)
* ``article.html`` — hand-maintained long-form guide
* ``plan.html``    — hand-maintained interactive planner

Usage::

    python3 scripts/build.py          # write index.html
    python3 scripts/build.py --check  # verify index.html is up to date (CI)
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SITE_URL = "https://aipmandy.github.io/intj-growth-guide"
EXPECTED_ITEMS = 41
MARKERS = ("/*__STYLE__*/", "/*__CATALOG__*/", "/*__APPLICATION__*/", "/*__JSONLD__*/")


def load_catalog() -> list[dict]:
    items = json.loads((ROOT / "data/catalog.json").read_text(encoding="utf-8"))
    if len(items) != EXPECTED_ITEMS:
        raise ValueError(f"Expected {EXPECTED_ITEMS} entries, got {len(items)}")
    return items


def json_for_script(payload: object) -> str:
    """Serialize for an inline <script> block without breaking out of the tag."""
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")


def structured_data(items: list[dict]) -> dict:
    return {
        "@context": "https://schema.org",
        "@type": "CollectionPage",
        "name": "INTJ 成长必看书影音图鉴",
        "alternateName": "INTJ ATLAS",
        "description": "41 部电影、电视剧、书籍与纪录片，六条成长路线，每条都配一个可以立刻执行的练习。",
        "url": SITE_URL + "/",
        "inLanguage": "zh-CN",
        "author": {
            "@type": "Person",
            "name": "AI 酋长 Andy",
            "url": "https://metaver.vip/",
        },
        "isPartOf": {
            "@type": "WebSite",
            "name": "INTJ ATLAS",
            "url": SITE_URL + "/",
        },
        "mainEntity": {
            "@type": "ItemList",
            "numberOfItems": len(items),
            "itemListElement": [
                {
                    "@type": "ListItem",
                    "position": index,
                    "name": item["title"],
                    "url": f"{SITE_URL}/article.html#{item['id']}",
                }
                for index, item in enumerate(items, start=1)
            ],
        },
    }


def render_index(items: list[dict]) -> str:
    template = (ROOT / "site/template.html").read_text(encoding="utf-8")
    css = (ROOT / "site/style.css").read_text(encoding="utf-8")
    js = (ROOT / "site/app.js").read_text(encoding="utf-8")

    for marker in MARKERS:
        if marker not in template:
            raise ValueError("Missing build marker: " + marker)

    return (
        template.replace("/*__STYLE__*/", css)
        .replace("/*__JSONLD__*/", json_for_script(structured_data(items)))
        .replace("/*__CATALOG__*/", json_for_script(items))
        .replace("/*__APPLICATION__*/", js)
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Build the INTJ ATLAS homepage.")
    parser.add_argument(
        "--check",
        action="store_true",
        help="Do not write files; fail if index.html differs from the generated output.",
    )
    args = parser.parse_args(argv)

    items = load_catalog()
    html = render_index(items)
    target = ROOT / "index.html"

    if args.check:
        current = target.read_text(encoding="utf-8") if target.exists() else ""
        if current != html:
            print(
                "index.html is out of date. Run `python3 scripts/build.py` and commit the result.",
                file=sys.stderr,
            )
            return 1
        print(f"index.html is up to date ({len(items)} items)")
        return 0

    target.write_text(html, encoding="utf-8")
    print(f"Built index.html ({len(items)} items, {len(html.encode('utf-8')) / 1024:.1f} KB)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
